HW.add("ru", {"nav.compare": "Сравнить", "fav.add": "Сохранить", "fav.saved": "Сохранено", "fav.filter": "Избранное", "fav.empty": "Пока ничего не сохранено. Нажмите на сердце у любых кроссовок, чтобы следить за ними здесь. Хранится только в этом браузере.", "cmp.btn": "Сравнить", "cmp.h1": "Сравнить", "cmp.sub": "Две пары. Один график. Смотрите, куда движется каждая.", "cmp.pickN": "Выберите кроссовки", "cmp.search": "Поиск по названию или SKU", "cmp.chart": "История цен", "cmp.pct": "Изменение %", "cmp.price": "Цена", "cmp.note": "Обе начинаются с 0% {d}, в первый общий день.", "cmp.nooverlap": "У этих двух пока нет общих дат.", "cmp.now": "Цена сейчас"});
HW.add("en", {"cmp.step": "Sneaker {n}", "cmp.details": "Details", "cmp.change": "Change sneaker:", "cmp.try": "Try one of these:", "cmp.since": "Since {d}:", "cmp.help": "How to read this: each colour is one sneaker. In % mode both lines start at 0, so you can see which one moved more whatever its price. Switch to Price to see real dollars. Estimates only."});
HW.add("es", {"cmp.step": "Zapatilla {n}", "cmp.details": "Detalles", "cmp.change": "Cambiar zapatilla:", "cmp.try": "Prueba una de estas:", "cmp.since": "Desde el {d}:", "cmp.help": "Cómo leerlo: cada color es una zapatilla. En modo % ambas líneas parten de 0, así ves cuál se movió más sin importar su precio. Cambia a Precio para ver dólares reales. Solo estimaciones."});
HW.add("fr", {"cmp.step": "Sneaker {n}", "cmp.details": "Détails", "cmp.change": "Changer de sneaker :", "cmp.try": "Essayez l'une d'elles :", "cmp.since": "Depuis le {d} :", "cmp.help": "Comment lire : chaque couleur est une sneaker. En mode %, les deux lignes partent de 0, vous voyez donc laquelle a le plus bougé, quel que soit son prix. Passez à Prix pour voir les dollars réels. Estimations uniquement."});
HW.add("it", {"cmp.step": "Sneaker {n}", "cmp.details": "Dettagli", "cmp.change": "Cambia sneaker:", "cmp.try": "Prova una di queste:", "cmp.since": "Dal {d}:", "cmp.help": "Come leggerlo: ogni colore è una sneaker. In modalità % le due linee partono da 0, così vedi quale si è mossa di più qualunque sia il prezzo. Passa a Prezzo per vedere i dollari reali. Solo stime."});
HW.add("ru", {"cmp.step": "Кроссовки {n}", "cmp.details": "Подробнее", "cmp.change": "Сменить кроссовки:", "cmp.try": "Попробуйте одну из них:", "cmp.since": "С {d}:", "cmp.help": "Как читать: каждый цвет — одни кроссовки. В режиме % обе линии начинаются с 0, поэтому видно, какие двигались сильнее, независимо от цены. Переключитесь на «Цена», чтобы увидеть доллары. Только оценки."});
HW.add("en", {"ft.track": "Signal record", "tr.h1": "Signal record", "tr.sub": "Every Cop and Sell signal we give is logged with its date and price. Then we check what happened after 7 and 30 days. Hits and misses, all public.", "tr.since": "Tracking since {d}", "tr.s.logged": "Signals logged", "tr.s.logged2": "{c} Cop · {s} Sell", "tr.s.checked": "Checked after 7 days", "tr.s.checked2": "Signals with a result", "tr.s.hit": "Hit rate (7 days)", "tr.s.hit2": "{h} of {n} signals", "tr.s.hit3": "Not shown yet: too few results", "tr.early": "Too early to judge. We show a hit rate only after at least {m} signals have been checked at 7 days. The first checks arrive around {d}.", "tr.hit": "hit", "tr.flat": "flat", "tr.miss": "miss", "tr.pending": "pending", "tr.nodata": "No data", "tr.howh": "How we score it", "tr.how": "A Cop is a hit if the price is more than 2% higher after 7 days. A Sell is a hit if it is more than 2% lower. Moves inside ±2% count as flat, and the opposite move counts as a miss. Each signal is logged once, not repeated every day while it lasts. Prices are our market estimates on that date.", "tr.limits": "Limits: small sample so far, one data source, and fees are not included. This is a public test of our own model, not a promise of results.", "tr.date": "Date", "tr.shoe": "Sneaker", "tr.sig": "Signal", "tr.p0": "Price then", "tr.p7": "After 7d", "tr.p30": "After 30d", "tr.res": "Result (7d)", "tr.empty": "No signals logged yet. Check back tomorrow.", "tr.more": "Show more", "al.h": "Price alert", "al.early": "early access", "al.p": "Get an email when this sneaker reaches your price or its signal changes. Prices are in USD.", "al.kind": "Alert me when", "al.below": "Price drops below", "al.above": "Price rises above", "al.cop": "Signal turns Cop", "al.sell": "Signal turns Sell", "al.thr": "Price (USD)", "al.email": "Your email", "al.consent": "I agree to receive email alerts about this sneaker. I can unsubscribe at any time.", "al.priv": "Privacy", "al.btn": "Create alert", "al.ok": "Saved. Alerts are in early access: we will email you a confirmation link first, and nothing is sent until you confirm.", "al.dup": "You already have this alert.", "al.limit": "You reached the limit of 5 alerts per email.", "al.busy": "Too many requests right now. Try again in a minute.", "al.err": "Something went wrong. Please try again later.", "al.bad": "Check your email address and price.", "al.needok": "Please tick the box to agree."});
HW.add("es", {"ft.track": "Historial de señales", "tr.h1": "Historial de señales", "tr.sub": "Cada señal Cop y Sell que damos se guarda con su fecha y precio. Luego comprobamos qué pasó a los 7 y 30 días. Aciertos y fallos, todo público.", "tr.since": "Seguimiento desde el {d}", "tr.s.logged": "Señales registradas", "tr.s.logged2": "{c} Cop · {s} Sell", "tr.s.checked": "Comprobadas a los 7 días", "tr.s.checked2": "Señales con resultado", "tr.s.hit": "Aciertos (7 días)", "tr.s.hit2": "{h} de {n} señales", "tr.s.hit3": "Aún no se muestra: pocos resultados", "tr.early": "Es pronto para juzgar. Solo mostramos el porcentaje cuando hay al menos {m} señales comprobadas a 7 días. Las primeras llegan hacia el {d}.", "tr.hit": "acierto", "tr.flat": "plano", "tr.miss": "fallo", "tr.pending": "pendiente", "tr.nodata": "Sin datos", "tr.howh": "Cómo lo puntuamos", "tr.how": "Un Cop es acierto si el precio sube más de un 2% a los 7 días. Un Sell es acierto si baja más de un 2%. Los movimientos dentro de ±2% cuentan como planos y el movimiento contrario como fallo. Cada señal se registra una vez, no se repite cada día. Los precios son nuestras estimaciones de mercado en esa fecha.", "tr.limits": "Límites: muestra pequeña por ahora, una sola fuente de datos y sin comisiones. Es una prueba pública de nuestro modelo, no una promesa de resultados.", "tr.date": "Fecha", "tr.shoe": "Zapatilla", "tr.sig": "Señal", "tr.p0": "Precio entonces", "tr.p7": "A 7 días", "tr.p30": "A 30 días", "tr.res": "Resultado (7d)", "tr.empty": "Aún no hay señales registradas. Vuelve mañana.", "tr.more": "Mostrar más", "al.h": "Alerta de precio", "al.early": "acceso anticipado", "al.p": "Recibe un email cuando esta zapatilla llegue a tu precio o cambie su señal. Precios en USD.", "al.kind": "Avísame cuando", "al.below": "El precio baje de", "al.above": "El precio suba de", "al.cop": "La señal sea Cop", "al.sell": "La señal sea Sell", "al.thr": "Precio (USD)", "al.email": "Tu email", "al.consent": "Acepto recibir alertas por email sobre esta zapatilla. Puedo darme de baja cuando quiera.", "al.priv": "Privacidad", "al.btn": "Crear alerta", "al.ok": "Guardado. Las alertas están en acceso anticipado: te enviaremos primero un enlace de confirmación y no se envía nada hasta que confirmes.", "al.dup": "Ya tienes esta alerta.", "al.limit": "Has alcanzado el límite de 5 alertas por email.", "al.busy": "Demasiadas solicitudes ahora. Inténtalo en un minuto.", "al.err": "Algo salió mal. Inténtalo más tarde.", "al.bad": "Revisa tu email y el precio.", "al.needok": "Marca la casilla para aceptar."});
HW.add("fr", {"ft.track": "Bilan des signaux", "tr.h1": "Bilan des signaux", "tr.sub": "Chaque signal Cop et Sell est enregistré avec sa date et son prix. Puis nous vérifions ce qui s'est passé après 7 et 30 jours. Réussites et échecs, tout est public.", "tr.since": "Suivi depuis le {d}", "tr.s.logged": "Signaux enregistrés", "tr.s.logged2": "{c} Cop · {s} Sell", "tr.s.checked": "Vérifiés après 7 jours", "tr.s.checked2": "Signaux avec résultat", "tr.s.hit": "Taux de réussite (7 jours)", "tr.s.hit2": "{h} signaux sur {n}", "tr.s.hit3": "Pas encore affiché : trop peu de résultats", "tr.early": "Trop tôt pour juger. Nous n'affichons un taux qu'à partir de {m} signaux vérifiés à 7 jours. Les premiers arrivent vers le {d}.", "tr.hit": "réussi", "tr.flat": "stable", "tr.miss": "raté", "tr.pending": "en attente", "tr.nodata": "Pas de données", "tr.howh": "Comment nous évaluons", "tr.how": "Un Cop est réussi si le prix monte de plus de 2 % après 7 jours. Un Sell est réussi s'il baisse de plus de 2 %. Les variations de ±2 % comptent comme stables, et le mouvement inverse comme un échec. Chaque signal est enregistré une fois, pas répété chaque jour. Les prix sont nos estimations de marché à cette date.", "tr.limits": "Limites : petit échantillon pour l'instant, une seule source de données, frais non inclus. C'est un test public de notre modèle, pas une promesse de résultats.", "tr.date": "Date", "tr.shoe": "Sneaker", "tr.sig": "Signal", "tr.p0": "Prix alors", "tr.p7": "À 7 j", "tr.p30": "À 30 j", "tr.res": "Résultat (7 j)", "tr.empty": "Aucun signal enregistré pour l'instant. Revenez demain.", "tr.more": "Afficher plus", "al.h": "Alerte de prix", "al.early": "accès anticipé", "al.p": "Recevez un e-mail quand cette sneaker atteint votre prix ou que son signal change. Prix en USD.", "al.kind": "Prévenez-moi quand", "al.below": "Le prix passe sous", "al.above": "Le prix dépasse", "al.cop": "Le signal passe à Cop", "al.sell": "Le signal passe à Sell", "al.thr": "Prix (USD)", "al.email": "Votre e-mail", "al.consent": "J'accepte de recevoir des alertes par e-mail sur cette sneaker. Je peux me désabonner à tout moment.", "al.priv": "Confidentialité", "al.btn": "Créer l'alerte", "al.ok": "Enregistré. Les alertes sont en accès anticipé : nous vous enverrons d'abord un lien de confirmation, et rien n'est envoyé avant votre confirmation.", "al.dup": "Vous avez déjà cette alerte.", "al.limit": "Vous avez atteint la limite de 5 alertes par e-mail.", "al.busy": "Trop de demandes en ce moment. Réessayez dans une minute.", "al.err": "Une erreur est survenue. Réessayez plus tard.", "al.bad": "Vérifiez votre e-mail et le prix.", "al.needok": "Veuillez cocher la case pour accepter."});
HW.add("it", {"ft.track": "Registro dei segnali", "tr.h1": "Registro dei segnali", "tr.sub": "Ogni segnale Cop e Sell che diamo viene registrato con data e prezzo. Poi controlliamo cosa è successo dopo 7 e 30 giorni. Successi ed errori, tutto pubblico.", "tr.since": "Monitoraggio dal {d}", "tr.s.logged": "Segnali registrati", "tr.s.logged2": "{c} Cop · {s} Sell", "tr.s.checked": "Controllati dopo 7 giorni", "tr.s.checked2": "Segnali con un risultato", "tr.s.hit": "Percentuale di successo (7 giorni)", "tr.s.hit2": "{h} segnali su {n}", "tr.s.hit3": "Non ancora mostrata: troppi pochi risultati", "tr.early": "Troppo presto per giudicare. Mostriamo la percentuale solo dopo almeno {m} segnali controllati a 7 giorni. I primi controlli arrivano intorno al {d}.", "tr.hit": "successo", "tr.flat": "piatto", "tr.miss": "errore", "tr.pending": "in attesa", "tr.nodata": "Nessun dato", "tr.howh": "Come lo valutiamo", "tr.how": "Un Cop è un successo se il prezzo sale di più del 2% dopo 7 giorni. Un Sell è un successo se scende di più del 2%. I movimenti entro ±2% contano come piatti, e il movimento opposto come errore. Ogni segnale è registrato una volta sola, non ripetuto ogni giorno. I prezzi sono le nostre stime di mercato in quella data.", "tr.limits": "Limiti: campione ancora piccolo, una sola fonte di dati e commissioni escluse. È un test pubblico del nostro modello, non una promessa di risultati.", "tr.date": "Data", "tr.shoe": "Sneaker", "tr.sig": "Segnale", "tr.p0": "Prezzo allora", "tr.p7": "Dopo 7g", "tr.p30": "Dopo 30g", "tr.res": "Esito (7g)", "tr.empty": "Ancora nessun segnale registrato. Torna domani.", "tr.more": "Mostra altro", "al.h": "Avviso di prezzo", "al.early": "accesso anticipato", "al.p": "Ricevi un'email quando questa sneaker raggiunge il tuo prezzo o cambia il suo segnale. Prezzi in USD.", "al.kind": "Avvisami quando", "al.below": "Il prezzo scende sotto", "al.above": "Il prezzo sale sopra", "al.cop": "Il segnale diventa Cop", "al.sell": "Il segnale diventa Sell", "al.thr": "Prezzo (USD)", "al.email": "La tua email", "al.consent": "Accetto di ricevere avvisi via email su questa sneaker. Posso annullare l'iscrizione in qualsiasi momento.", "al.priv": "Privacy", "al.btn": "Crea avviso", "al.ok": "Salvato. Gli avvisi sono in accesso anticipato: ti invieremo prima un link di conferma e non verrà inviato nulla finché non confermi.", "al.dup": "Hai già questo avviso.", "al.limit": "Hai raggiunto il limite di 5 avvisi per email.", "al.busy": "Troppe richieste in questo momento. Riprova tra un minuto.", "al.err": "Qualcosa è andato storto. Riprova più tardi.", "al.bad": "Controlla l'email e il prezzo.", "al.needok": "Spunta la casella per accettare."});
HW.add("ru", {"ft.track": "Результаты сигналов", "tr.h1": "Результаты сигналов", "tr.sub": "Каждый сигнал Cop и Sell записывается с датой и ценой. Затем мы проверяем, что произошло через 7 и 30 дней. Попадания и промахи — всё публично.", "tr.since": "Отслеживаем с {d}", "tr.s.logged": "Записано сигналов", "tr.s.logged2": "{c} Cop · {s} Sell", "tr.s.checked": "Проверено через 7 дней", "tr.s.checked2": "Сигналов с результатом", "tr.s.hit": "Доля попаданий (7 дней)", "tr.s.hit2": "{h} из {n} сигналов", "tr.s.hit3": "Пока не показываем: мало результатов", "tr.early": "Пока рано судить. Мы покажем долю попаданий, когда проверим не менее {m} сигналов через 7 дней. Первые проверки около {d}.", "tr.hit": "попал", "tr.flat": "ровно", "tr.miss": "промах", "tr.pending": "ожидает", "tr.nodata": "Нет данных", "tr.howh": "Как мы оцениваем", "tr.how": "Cop считается попаданием, если цена через 7 дней выросла более чем на 2%. Sell — если упала более чем на 2%. Движение в пределах ±2% считается ровным, а противоположное — промахом. Каждый сигнал записывается один раз, а не повторяется каждый день. Цены — наши рыночные оценки на эту дату.", "tr.limits": "Ограничения: пока маленькая выборка, один источник данных, комиссии не учитываются. Это публичная проверка нашей модели, а не обещание результата.", "tr.date": "Дата", "tr.shoe": "Кроссовки", "tr.sig": "Сигнал", "tr.p0": "Цена тогда", "tr.p7": "Через 7 дн.", "tr.p30": "Через 30 дн.", "tr.res": "Итог (7 дн.)", "tr.empty": "Сигналов пока нет. Загляните завтра.", "tr.more": "Показать ещё", "al.h": "Ценовое уведомление", "al.early": "ранний доступ", "al.p": "Получите письмо, когда цена достигнет нужной или сигнал изменится. Цены в USD.", "al.kind": "Уведомить, когда", "al.below": "Цена опустится ниже", "al.above": "Цена поднимется выше", "al.cop": "Сигнал станет Cop", "al.sell": "Сигнал станет Sell", "al.thr": "Цена (USD)", "al.email": "Ваш email", "al.consent": "Я согласен получать уведомления по email об этих кроссовках. Могу отписаться в любое время.", "al.priv": "Конфиденциальность", "al.btn": "Создать уведомление", "al.ok": "Сохранено. Уведомления в раннем доступе: сначала мы пришлём ссылку для подтверждения, и ничего не отправляется до неё.", "al.dup": "Такое уведомление уже есть.", "al.limit": "Достигнут лимит: 5 уведомлений на один email.", "al.busy": "Слишком много запросов. Повторите через минуту.", "al.err": "Что-то пошло не так. Попробуйте позже.", "al.bad": "Проверьте email и цену.", "al.needok": "Поставьте галочку согласия."});
HW.add("en", {"hero.lead": "Hypewise collects US resale prices every day and turns the history into a clear signal: Cop, Wait or Sell. See where a pair is heading before you buy or sell, and check how often our calls were right.", "hero.cta2": "Compare sneakers", "do.h": "Everything you need to decide", "do.intro": "Four tools, one goal: know whether it is a good moment to buy, wait or sell.", "do1.h": "Browse prices", "do1.p": "Hundreds of sneakers with daily prices, 7-day change and charts.", "do2.h": "Compare two sneakers", "do2.p": "Price, trend and signal side by side, on one chart.", "do3.h": "Save and get alerts", "do3.p": "Tap the heart to follow a pair. Set a price alert by email (early access).", "do4.h": "Signal record", "do4.p": "Every call is logged and checked after 7 and 30 days. Hits and misses, public.", "do.go": "Open", "how.intro": "From raw prices to a clear call, in three automatic steps.", "s1.h": "We collect the data", "s1.p": "Every day we record US resale prices for hundreds of the most traded models and keep the full history.", "s2.h": "We clean it", "s2.p": "We discard wrong models, accessories, outdated listings and out-of-range prices, so only reliable readings are left.", "s3.h": "We turn it into a signal", "s3.p": "Five factors on each price history give a call (Cop, Wait or Sell) with a confidence level and the reasons written out.", "sig.h": "The Hypewise signal", "sig.intro": "Seeing a price is easy. Knowing what to do with it is the hard part. Hypewise collects the data every day and reads each price history to suggest whether it looks like a good moment to buy, to wait or to sell, always with the reasons and a confidence level.", "sig.proof.h": "What makes it different", "sig.proof.p": "We don't just give a call: we log every Cop and Sell with its date and price, check it 7 and 30 days later and publish the results, misses included.", "sig.proof.btn": "See the signal record", "cm.eyebrow": "Young project", "cm.h": "We're just getting started. Help us grow.", "cm.p1": "Hypewise is a young, independent project built in public on GitHub. Every day we add data and improve the signal.", "cm.p2": "Questions, feedback, ideas, partnerships, or want to support us? Write to us. We reply to everyone.", "cm.mailbtn": "Write to us", "cm.whead": "Ways to help", "cm.w1": "Follow us on X", "cm.w2": "Share Hypewise with a friend", "cm.w3": "Tell us about a wrong price or a missing sneaker", "cm.w4": "Partnerships and investment: email us", "fh.h": "We're a young project", "fh.p": "Questions, feedback or want to support us? Write to us, we reply to everyone.", "bn.4": "Young project, growing every week. Questions or want to support us? Write to us", "b.sub": "US resale prices in dollars, updated daily. Open any sneaker for its chart and signal, or compare two side by side.", "cb.h": "Compare two sneakers", "cb.p": "Tap ⇄ on any two cards to see price, trend and signal side by side.", "cb.btn": "Open compare", "cb.add": "Add to compare", "cb.rem": "Remove from compare", "cb.one": "{a} selected. Pick one more to compare.", "cb.vs": "{a} vs {b}", "sg.analysis": "Hypewise signal", "sg.lead": "Built from this sneaker's own price history, collected every day. It suggests whether it looks like a good moment to buy, wait or sell.", "sg.collect": "Collecting data: {n} of {need} readings", "sg.none2": "The signal appears once we have at least 8 readings over 7 or more days. Until then we prefer not to give a call.", "sg.why": "What drives the signal", "sg.track": "See how often our signals were right", "cc.h": "Compare with another sneaker", "cc.p": "See two sneakers side by side: price, trend and signal on one chart.", "d.other": "Check other marketplaces", "d.otherp": "Open this pair elsewhere to see live prices. Prices there are not shown here, and may differ.", "sh.share": "Share"});
HW.add("es", {"hero.lead": "Hypewise recopila cada día los precios de reventa de EE. UU. y convierte el historial en una señal clara: Cop, Wait o Sell. Mira hacia dónde va un par antes de comprar o vender y comprueba cuántas veces acertamos.", "hero.cta2": "Comparar zapatillas", "do.h": "Todo lo que necesitas para decidir", "do.intro": "Cuatro herramientas, un objetivo: saber si es buen momento para comprar, esperar o vender.", "do1.h": "Explora precios", "do1.p": "Cientos de zapatillas con precios diarios, cambio a 7 días y gráficos.", "do2.h": "Compara dos zapatillas", "do2.p": "Precio, tendencia y señal lado a lado, en un solo gráfico.", "do3.h": "Guarda y recibe alertas", "do3.p": "Toca el corazón para seguir un par. Crea una alerta de precio por email (acceso anticipado).", "do4.h": "Historial de señales", "do4.p": "Cada señal se guarda y se comprueba a los 7 y 30 días. Aciertos y fallos, públicos.", "do.go": "Abrir", "how.intro": "De los precios en bruto a una señal clara, en tres pasos automáticos.", "s1.h": "Recopilamos los datos", "s1.p": "Cada día registramos los precios de reventa en EE. UU. de cientos de modelos muy demandados y guardamos todo el historial.", "s2.h": "Lo depuramos", "s2.p": "Descartamos modelos equivocados, accesorios, datos antiguos y precios fuera de rango, para quedarnos solo con lecturas fiables.", "s3.h": "Lo convertimos en señal", "s3.p": "Cinco factores sobre cada historial dan una señal (Cop, Wait o Sell) con nivel de confianza y los motivos por escrito.", "sig.h": "La señal Hypewise", "sig.intro": "Ver un precio es fácil. Saber qué hacer con él es lo difícil. Hypewise recopila los datos cada día y analiza cada historial de precios para sugerir si parece un buen momento para comprar, esperar o vender, siempre con los motivos y un nivel de confianza.", "sig.proof.h": "Qué lo hace diferente", "sig.proof.p": "No solo damos una señal: guardamos cada Cop y Sell con su fecha y precio, los comprobamos a los 7 y 30 días y publicamos los resultados, también los fallos.", "sig.proof.btn": "Ver el historial de señales", "cm.eyebrow": "Proyecto joven", "cm.h": "Estamos empezando. Ayúdanos a crecer.", "cm.p1": "Hypewise es un proyecto joven e independiente, construido en público en GitHub. Cada día añadimos datos y mejoramos la señal.", "cm.p2": "¿Preguntas, comentarios, ideas, colaboraciones o quieres apoyarnos? Escríbenos. Respondemos a todos.", "cm.mailbtn": "Escríbenos", "cm.whead": "Formas de ayudar", "cm.w1": "Síguenos en X", "cm.w2": "Comparte Hypewise con un amigo", "cm.w3": "Avísanos de un precio erróneo o una zapatilla que falta", "cm.w4": "Colaboraciones e inversión: escríbenos", "fh.h": "Somos un proyecto joven", "fh.p": "¿Preguntas, comentarios o quieres apoyarnos? Escríbenos, respondemos a todos.", "bn.4": "Proyecto joven que crece cada semana. ¿Preguntas o quieres apoyarnos? Escríbenos", "b.sub": "Precios de reventa de EE. UU. en dólares, actualizados cada día. Abre cualquier zapatilla para ver su gráfico y señal, o compara dos lado a lado.", "cb.h": "Compara dos zapatillas", "cb.p": "Toca ⇄ en dos tarjetas cualquiera para ver precio, tendencia y señal lado a lado.", "cb.btn": "Abrir comparador", "cb.add": "Añadir a la comparación", "cb.rem": "Quitar de la comparación", "cb.one": "{a} seleccionada. Elige una más para comparar.", "cb.vs": "{a} vs {b}", "sg.analysis": "Señal Hypewise", "sg.lead": "Basada en el historial de precios de este par, recopilado cada día. Sugiere si parece buen momento para comprar, esperar o vender.", "sg.collect": "Recopilando datos: {n} de {need} lecturas", "sg.none2": "La señal aparece cuando tenemos al menos 8 lecturas en 7 o más días. Hasta entonces preferimos no dar una opinión.", "sg.why": "Qué impulsa la señal", "sg.track": "Mira cuántas veces acertamos", "cc.h": "Compara con otra zapatilla", "cc.p": "Mira dos zapatillas lado a lado: precio, tendencia y señal en un gráfico.", "d.other": "Consulta otros mercados", "d.otherp": "Abre este par en otras webs para ver precios en directo. Los precios de allí no se muestran aquí y pueden diferir.", "sh.share": "Compartir"});
HW.add("fr", {"hero.lead": "Hypewise collecte chaque jour les prix de revente américains et transforme l'historique en un signal clair : Cop, Wait ou Sell. Voyez où va une paire avant d'acheter ou de vendre, et vérifiez combien de fois nous avions raison.", "hero.cta2": "Comparer des sneakers", "do.h": "Tout pour décider", "do.intro": "Quatre outils, un objectif : savoir s'il est temps d'acheter, d'attendre ou de vendre.", "do1.h": "Parcourir les prix", "do1.p": "Des centaines de sneakers avec prix quotidiens, variation sur 7 jours et graphiques.", "do2.h": "Comparer deux sneakers", "do2.p": "Prix, tendance et signal côte à côte, sur un seul graphique.", "do3.h": "Enregistrer et être alerté", "do3.p": "Touchez le cœur pour suivre une paire. Créez une alerte de prix par e-mail (accès anticipé).", "do4.h": "Bilan des signaux", "do4.p": "Chaque signal est enregistré et vérifié après 7 et 30 jours. Réussites et échecs, publics.", "do.go": "Ouvrir", "how.intro": "Des prix bruts à un avis clair, en trois étapes automatiques.", "s1.h": "Nous collectons les données", "s1.p": "Chaque jour, nous relevons les prix de revente américains de centaines de modèles très échangés et conservons tout l'historique.", "s2.h": "Nous le nettoyons", "s2.p": "Nous écartons les mauvais modèles, accessoires, données périmées et prix aberrants, pour ne garder que des relevés fiables.", "s3.h": "Nous en faisons un signal", "s3.p": "Cinq facteurs sur chaque historique donnent un avis (Cop, Wait ou Sell) avec un niveau de confiance et les raisons détaillées.", "sig.h": "Le signal Hypewise", "sig.intro": "Voir un prix est facile. Savoir quoi en faire est plus difficile. Hypewise collecte les données chaque jour et analyse chaque historique pour suggérer s'il semble judicieux d'acheter, d'attendre ou de vendre, toujours avec les raisons et un niveau de confiance.", "sig.proof.h": "Ce qui le distingue", "sig.proof.p": "Nous ne nous contentons pas de donner un avis : nous enregistrons chaque Cop et Sell avec sa date et son prix, le vérifions 7 et 30 jours plus tard et publions les résultats, échecs compris.", "sig.proof.btn": "Voir le bilan des signaux", "cm.eyebrow": "Jeune projet", "cm.h": "Nous débutons. Aidez-nous à grandir.", "cm.p1": "Hypewise est un jeune projet indépendant, construit en public sur GitHub. Chaque jour, nous ajoutons des données et améliorons le signal.", "cm.p2": "Questions, retours, idées, partenariats ou envie de nous soutenir ? Écrivez-nous. Nous répondons à tout le monde.", "cm.mailbtn": "Écrivez-nous", "cm.whead": "Façons d'aider", "cm.w1": "Suivez-nous sur X", "cm.w2": "Partagez Hypewise avec un ami", "cm.w3": "Signalez-nous un prix erroné ou une sneaker manquante", "cm.w4": "Partenariats et investissement : écrivez-nous", "fh.h": "Nous sommes un jeune projet", "fh.p": "Des questions, un avis ou envie de nous soutenir ? Écrivez-nous, nous répondons à tout le monde.", "bn.4": "Jeune projet qui grandit chaque semaine. Des questions ou envie de nous soutenir ? Écrivez-nous", "b.sub": "Prix de revente américains en dollars, mis à jour chaque jour. Ouvrez une sneaker pour son graphique et son signal, ou comparez-en deux côte à côte.", "cb.h": "Comparer deux sneakers", "cb.p": "Touchez ⇄ sur deux cartes pour voir prix, tendance et signal côte à côte.", "cb.btn": "Ouvrir le comparateur", "cb.add": "Ajouter à la comparaison", "cb.rem": "Retirer de la comparaison", "cb.one": "{a} sélectionnée. Choisissez-en une autre.", "cb.vs": "{a} vs {b}", "sg.analysis": "Signal Hypewise", "sg.lead": "Basé sur l'historique de prix de cette paire, collecté chaque jour. Il suggère s'il semble judicieux d'acheter, d'attendre ou de vendre.", "sg.collect": "Collecte en cours : {n} relevés sur {need}", "sg.none2": "Le signal apparaît dès que nous avons au moins 8 relevés sur 7 jours ou plus. D'ici là, nous préférons ne pas donner d'avis.", "sg.why": "Ce qui fait le signal", "sg.track": "Voir combien de fois nous avions raison", "cc.h": "Comparer avec une autre sneaker", "cc.p": "Voyez deux sneakers côte à côte : prix, tendance et signal sur un graphique.", "d.other": "Voir d'autres places de marché", "d.otherp": "Ouvrez cette paire ailleurs pour voir les prix en direct. Ces prix ne sont pas affichés ici et peuvent différer.", "sh.share": "Partager"});
HW.add("it", {"hero.lead": "Hypewise raccoglie ogni giorno i prezzi di rivendita USA e trasforma lo storico in un segnale chiaro: Cop, Wait o Sell. Scopri dove sta andando un paio prima di comprare o vendere e controlla quante volte abbiamo avuto ragione.", "hero.cta2": "Confronta le sneaker", "do.h": "Tutto quello che serve per decidere", "do.intro": "Quattro strumenti, un obiettivo: capire se è il momento di comprare, aspettare o vendere.", "do1.h": "Esplora i prezzi", "do1.p": "Centinaia di sneaker con prezzi giornalieri, variazione a 7 giorni e grafici.", "do2.h": "Confronta due sneaker", "do2.p": "Prezzo, tendenza e segnale affiancati, su un unico grafico.", "do3.h": "Salva e ricevi avvisi", "do3.p": "Tocca il cuore per seguire un paio. Crea un avviso di prezzo via email (accesso anticipato).", "do4.h": "Registro dei segnali", "do4.p": "Ogni segnale viene registrato e controllato dopo 7 e 30 giorni. Successi ed errori, pubblici.", "do.go": "Apri", "how.intro": "Dai prezzi grezzi a un'indicazione chiara, in tre passaggi automatici.", "s1.h": "Raccogliamo i dati", "s1.p": "Ogni giorno registriamo i prezzi di rivendita USA di centinaia di modelli tra i più scambiati e conserviamo tutto lo storico.", "s2.h": "Lo ripuliamo", "s2.p": "Scartiamo modelli sbagliati, accessori, dati vecchi e prezzi fuori scala, così restano solo rilevazioni affidabili.", "s3.h": "Lo trasformiamo in segnale", "s3.p": "Cinque fattori su ogni storico danno un'indicazione (Cop, Wait o Sell) con un livello di affidabilità e i motivi scritti.", "sig.h": "Il segnale Hypewise", "sig.intro": "Vedere un prezzo è facile. Capire cosa farne è la parte difficile. Hypewise raccoglie i dati ogni giorno e legge ogni storico dei prezzi per suggerire se sembra un buon momento per comprare, aspettare o vendere, sempre con i motivi e un livello di affidabilità.", "sig.proof.h": "Cosa lo rende diverso", "sig.proof.p": "Non ci limitiamo a dare un'indicazione: registriamo ogni Cop e Sell con data e prezzo, lo controlliamo dopo 7 e 30 giorni e pubblichiamo i risultati, errori compresi.", "sig.proof.btn": "Vedi il registro dei segnali", "cm.eyebrow": "Progetto giovane", "cm.h": "Siamo agli inizi. Aiutaci a crescere.", "cm.p1": "Hypewise è un progetto giovane e indipendente, costruito in pubblico su GitHub. Ogni giorno aggiungiamo dati e miglioriamo il segnale.", "cm.p2": "Domande, feedback, idee, collaborazioni o vuoi supportarci? Scrivici. Rispondiamo a tutti.", "cm.mailbtn": "Scrivici", "cm.whead": "Come aiutarci", "cm.w1": "Seguici su X", "cm.w2": "Condividi Hypewise con un amico", "cm.w3": "Segnalaci un prezzo sbagliato o una sneaker mancante", "cm.w4": "Collaborazioni e investimenti: scrivici", "fh.h": "Siamo un progetto giovane", "fh.p": "Domande, feedback o vuoi supportarci? Scrivici, rispondiamo a tutti.", "bn.4": "Progetto giovane in crescita ogni settimana. Domande o vuoi supportarci? Scrivici", "b.sub": "Prezzi di rivendita USA in dollari, aggiornati ogni giorno. Apri una sneaker per grafico e segnale, o confrontane due affiancate.", "cb.h": "Confronta due sneaker", "cb.p": "Tocca ⇄ su due schede qualsiasi per vedere prezzo, tendenza e segnale affiancati.", "cb.btn": "Apri il confronto", "cb.add": "Aggiungi al confronto", "cb.rem": "Rimuovi dal confronto", "cb.one": "{a} selezionata. Scegline un'altra da confrontare.", "cb.vs": "{a} vs {b}", "sg.analysis": "Segnale Hypewise", "sg.lead": "Basato sullo storico dei prezzi di questo paio, raccolto ogni giorno. Suggerisce se sembra un buon momento per comprare, aspettare o vendere.", "sg.collect": "Raccolta dati: {n} rilevazioni su {need}", "sg.none2": "Il segnale compare quando abbiamo almeno 8 rilevazioni in 7 o più giorni. Fino ad allora preferiamo non dare indicazioni.", "sg.why": "Cosa determina il segnale", "sg.track": "Scopri quante volte abbiamo avuto ragione", "cc.h": "Confronta con un'altra sneaker", "cc.p": "Guarda due sneaker affiancate: prezzo, tendenza e segnale su un unico grafico.", "d.other": "Controlla altri marketplace", "d.otherp": "Apri questo paio su altri siti per vedere i prezzi in tempo reale. I prezzi di lì non sono mostrati qui e possono differire.", "sh.share": "Condividi"});
HW.add("ru", {"hero.lead": "Hypewise каждый день собирает цены перепродажи в США и превращает историю в понятный сигнал: Cop, Wait или Sell. Узнайте, куда движется пара, прежде чем покупать или продавать, и проверьте, как часто мы оказывались правы.", "hero.cta2": "Сравнить кроссовки", "do.h": "Всё, что нужно для решения", "do.intro": "Четыре инструмента, одна цель: понять, пора ли покупать, ждать или продавать.", "do1.h": "Смотреть цены", "do1.p": "Сотни кроссовок с ежедневными ценами, изменением за 7 дней и графиками.", "do2.h": "Сравнить две пары", "do2.p": "Цена, тренд и сигнал рядом, на одном графике.", "do3.h": "Сохраняйте и получайте уведомления", "do3.p": "Нажмите на сердце, чтобы следить за парой. Создайте ценовое уведомление по email (ранний доступ).", "do4.h": "Результаты сигналов", "do4.p": "Каждый сигнал записывается и проверяется через 7 и 30 дней. Попадания и промахи — публично.", "do.go": "Открыть", "how.intro": "От сырых цен до понятного сигнала за три автоматических шага.", "s1.h": "Мы собираем данные", "s1.p": "Каждый день мы фиксируем цены перепродажи в США для сотен самых востребованных моделей и храним всю историю.", "s2.h": "Мы очищаем их", "s2.p": "Мы отбрасываем неверные модели, аксессуары, устаревшие данные и аномальные цены, оставляя только надёжные значения.", "s3.h": "Превращаем в сигнал", "s3.p": "Пять факторов по каждой истории цен дают вывод (Cop, Wait или Sell) с уровнем уверенности и объяснением.", "sig.h": "Сигнал Hypewise", "sig.intro": "Увидеть цену легко. Понять, что с ней делать, — сложнее. Hypewise каждый день собирает данные и анализирует историю цен каждой пары, чтобы подсказать, подходящий ли момент покупать, ждать или продавать, — всегда с причинами и уровнем уверенности.", "sig.proof.h": "В чём отличие", "sig.proof.p": "Мы не просто даём вывод: записываем каждый Cop и Sell с датой и ценой, проверяем через 7 и 30 дней и публикуем результаты, включая промахи.", "sig.proof.btn": "Смотреть результаты сигналов", "cm.eyebrow": "Молодой проект", "cm.h": "Мы только начинаем. Помогите нам расти.", "cm.p1": "Hypewise — молодой независимый проект, который строится открыто на GitHub. Каждый день мы добавляем данные и улучшаем сигнал.", "cm.p2": "Вопросы, отзывы, идеи, партнёрство или хотите нас поддержать? Напишите нам. Мы отвечаем всем.", "cm.mailbtn": "Напишите нам", "cm.whead": "Как помочь", "cm.w1": "Подписывайтесь на нас в X", "cm.w2": "Поделитесь Hypewise с другом", "cm.w3": "Сообщите об ошибочной цене или отсутствующей паре", "cm.w4": "Партнёрство и инвестиции: пишите нам", "fh.h": "Мы молодой проект", "fh.p": "Вопросы, отзывы или хотите нас поддержать? Напишите нам — мы отвечаем всем.", "bn.4": "Молодой проект, растущий каждую неделю. Вопросы или хотите нас поддержать? Напишите нам", "b.sub": "Цены перепродажи в США в долларах, обновляются каждый день. Откройте любую пару — график и сигнал, или сравните две рядом.", "cb.h": "Сравните две пары", "cb.p": "Нажмите ⇄ на любых двух карточках, чтобы увидеть цену, тренд и сигнал рядом.", "cb.btn": "Открыть сравнение", "cb.add": "Добавить к сравнению", "cb.rem": "Убрать из сравнения", "cb.one": "Выбрано: {a}. Выберите ещё одну.", "cb.vs": "{a} vs {b}", "sg.analysis": "Сигнал Hypewise", "sg.lead": "Основан на истории цен этой пары, которую мы собираем каждый день. Подсказывает, подходящий ли момент покупать, ждать или продавать.", "sg.collect": "Сбор данных: {n} из {need} значений", "sg.none2": "Сигнал появится, когда у нас будет не менее 8 значений за 7 и более дней. До этого мы предпочитаем не давать вывод.", "sg.why": "Что формирует сигнал", "sg.track": "Узнать, как часто мы оказывались правы", "cc.h": "Сравнить с другой парой", "cc.p": "Две пары рядом: цена, тренд и сигнал на одном графике.", "d.other": "Проверить другие площадки", "d.otherp": "Откройте пару на других сайтах, чтобы увидеть актуальные цены. Они здесь не показываются и могут отличаться.", "sh.share": "Поделиться"});